select m.*, u.name unitName, mc.name categoryName, me.id meId, me.spec_values sku, me.sku_code skuCode, me.spec_values specValues, ifnull(me.purchase_decimal,0) purchaseDecimal, mi.unit_code unitCode, mi.unit_code mBarCode, case when mi.status='IN_STOCK' then '在库' else mi.status end unitStatus, mi.inbound_time inboundTime, d.name depotName, 1 currentStock, ifnull(me.purchase_decimal,0) currentStockPrice, ifnull(m.weight,0) currentWeight, case when mi.inbound_type='INITIAL' then 1 else 0 end initialStock from jsh_material_instance mi join jsh_material m on m.id=mi.material_id and ifnull(m.delete_flag,'0')!='1' left join jsh_material_extend me on me.id=mi.material_extend_id and ifnull(me.delete_flag,'0')!='1' left join jsh_unit u on u.name = m.unit and ifnull(u.delete_flag,'0')!='1' left join jsh_material_category mc on m.category_id=mc.id and ifnull(mc.delete_flag,'0')!='1' left join jsh_depot d on d.id=mi.current_depot_id and ifnull(d.delete_flag,'0')!='1' where mi.status='IN_STOCK' and ifnull(mi.delete_flag,'0')!='1' and mi.tenant_id=#{tenantId}
and mi.current_depot_id in #{depotId}
and m.category_id in #{id}
and m.position like concat('%',#{position},'%')
and (mi.unit_code like concat('%',#{materialParam},'%') or mi.sku_code like concat('%',#{materialParam},'%') or me.sku_code like concat('%',#{materialParam},'%') or me.spec_values like concat('%',#{materialParam},'%') or m.bar_code like concat('%',#{materialParam},'%') or m.name like concat('%',#{materialParam},'%') or m.mnemonic like concat('%',#{materialParam},'%') or m.brand like concat('%',#{materialParam},'%') or m.mfrs like concat('%',#{materialParam},'%') or me.spec_values like concat('%',#{materialParam},'%'))
order by mi.id desc limit #{offset},#{rows}

