jme.purchase_decimal, jme.commodity_decimal, jme.wholesale_decimal, jme.low_decimal, jme.spec_values sku
from (select m.id, min(me.id) meId
from jsh_material m
left join jsh_material_extend me on m.id = me.material_id and ifnull(me.delete_Flag,'0') !='1'
where 1=1


    and (m.bar_code like #{bindKey} or m.name like #{bindKey} or m.mnemonic like #{bindKey} or m.brand like #{bindKey} or m.mfrs like #{bindKey})






    and m.brand like #{bindBrand}



    and m.mfrs like #{bindMfrs}



    and m.other_field1 like #{bindOtherField1}



    and m.other_field2 like #{bindOtherField2}



    and m.other_field3 like #{bindOtherField3}



    and m.other_field4 like #{bindOtherField4}



    and m.other_field5 like #{bindOtherField5}



    and m.other_field6 like #{bindOtherField6}



    and m.other_field7 like #{bindOtherField7}


    and m.weight = #{weight}



    and m.enable_serial_number = #{enableSerialNumber}


    and m.enable_batch_number = #{enableBatchNumber}



    and m.position like #{bindPosition}




    and m.remark like #{bindRemark}


    and m.category_id in

        #{item}


and ifnull(m.delete_flag,'0') !='1'
group by m.id
order by m.id desc) tb
left join jsh_material jm on tb.id = jm.id and ifnull(jm.delete_Flag,'0') !='1'
left join jsh_material_extend jme on tb.meId = jme.id and ifnull(jme.delete_Flag,'0') !='1'
left join jsh_unit u on u.name = jm.unit and ifnull(u.delete_Flag,'0') !='1'
left join jsh_material_category mc on jm.category_id = mc.id and ifnull(mc.delete_Flag,'0') !='1'
order by tb.id desc

select jm.*, u.name unit_name, mc.name categoryName, jme.id meId, jm.bar_code m_bar_code,
jme.purchase_decimal, jme.commodity_decimal, jme.wholesale_decimal, jme.low_decimal,
jme.spec_values sku, jme.sku_code, jme.spec_values specValues, jm.unit,
jme.store, jme.default_flag,
s.sku_name, s.spec_json, s.spec_summary, s.market_price,
date_format(s.create_time,'%Y-%m-%d %H:%i:%s') sku_create_time,
date_format(s.update_time,'%Y-%m-%d %H:%i:%s') sku_update_time,
coalesce((select ss.image_url from sku_spec ss
        where ss.sku_id = s.id and ss.image_url is not null and ss.image_url <> '' limit 1), jme.img_url) as imgName,
coalesce((select sum(mcs.current_number) from jsh_material_current_stock mcs
        where mcs.material_id = jm.id
          and (mcs.material_extend_id = jme.id or (mcs.material_extend_id is null and jme.default_flag = 1))
          and ifnull(mcs.delete_flag,'0') !='1'),
         (select sum(mis.number) from jsh_material_initial_stock mis
        where mis.material_id = jm.id
          and (mis.material_extend_id = jme.id or (mis.material_extend_id is null and jme.default_flag = 1))
          and ifnull(mis.delete_flag,'0') !='1'), 0) as stock,
ifnull((select sum(mis.number) from jsh_material_initial_stock mis
        where mis.material_id = jm.id
          and (mis.material_extend_id = jme.id or (mis.material_extend_id is null and jme.default_flag = 1))
          and ifnull(mis.delete_flag,'0') !='1'), 0) as initial_stock
from jsh_material jm
left join jsh_material_extend jme on jm.id = jme.material_id and ifnull(jme.delete_flag,'0') !='1'
left join sku s on s.spu_id = jm.id and s.sku_code = jme.sku_code and s.deleted_at is null
left join jsh_unit u on u.name = jm.unit and ifnull(u.delete_flag,'0') !='1'
left join jsh_material_category mc on jm.category_id = mc.id and ifnull(mc.delete_flag,'0') !='1'
where 1=1


    and (jm.bar_code like #{bindKey} or jm.bar_code like #{bindKey} or jme.sku_code like #{bindKey} or jm.name like #{bindKey}
    or jm.mnemonic like #{bindKey} or jm.brand like #{bindKey} or jm.mfrs like #{bindKey})






    and jm.brand like #{bindBrand}



    and jm.mfrs like #{bindMfrs}



    and jm.other_field1 like #{bindOtherField1}



    and jm.other_field2 like #{bindOtherField2}



    and jm.other_field3 like #{bindOtherField3}



    and jm.other_field4 like #{bindOtherField4}



    and jm.other_field5 like #{bindOtherField5}



    and jm.other_field6 like #{bindOtherField6}



    and jm.other_field7 like #{bindOtherField7}


    and jm.weight = #{weight}



    and jm.enable_serial_number = #{enableSerialNumber}


    and jm.enable_batch_number = #{enableBatchNumber}



    and jm.position like #{bindPosition}



    and jm.remark like #{bindRemark}


    and jm.category_id in

        #{item}


and ifnull(jm.delete_flag,'0') !='1'
order by jm.id desc, jme.default_flag desc, jme.id asc

