select count(*) from ( select me.id, ifnull((select sum(mcs.current_number) from jsh_material_current_stock mcs where mcs.material_id=m.id and (mcs.material_extend_id=me.id or (mcs.material_extend_id is null and me.default_flag=1)) and ifnull(mcs.delete_flag,'0')!='1'
and mcs.depot_id in #{depotId} ),0) currentStock from jsh_material m join jsh_material_extend me on me.material_id=m.id and ifnull(me.delete_flag,'0')!='1' where ifnull(m.delete_flag,'0')!='1'
and m.category_id in #{id}
