and (m.bar_code like concat('%',#{materialParam},'%') or me.sku_code like concat('%',#{materialParam},'%') or me.spec_values like concat('%',#{materialParam},'%') or m.bar_code like concat('%',#{materialParam},'%') or m.name like concat('%',#{materialParam},'%') or m.mnemonic like concat('%',#{materialParam},'%') or m.brand like concat('%',#{materialParam},'%') or m.mfrs like concat('%',#{materialParam},'%') or m.other_field1 like concat('%',#{materialParam},'%') or m.other_field2 like concat('%',#{materialParam},'%') or m.other_field3 like concat('%',#{materialParam},'%') or m.other_field4 like concat('%',#{materialParam},'%') or m.other_field5 like concat('%',#{materialParam},'%') or m.other_field6 like concat('%',#{materialParam},'%') or m.other_field7 like concat('%',#{materialParam},'%'))
) sku_rows where ifnull(sku_rows.currentStock,0)!=0

select m.id, m.name, m.brand, m.mfrs, m.position, me.img_url as imgName, m.unit unitName, mc.name categoryName, coalesce(nullif(me.sku_code,''), nullif(m.bar_code,'')) mBarCode, ifnull(me.purchase_decimal,0) purchaseDecimal, ifnull(mcs.current_unit_price,0) currentUnitPrice, ifnull(sum(mcs.current_number),0) currentStock, sum(ifnull(me.purchase_decimal, 0) * ifnull(mcs.current_number, 0)) currentStockPrice, sum(ifnull(mcs.current_unit_price, 0) * ifnull(mcs.current_number, 0)) currentStockMovePrice, sum(ifnull(m.weight, 0) * ifnull(mcs.current_number, 0)) currentWeight FROM jsh_material m left JOIN jsh_material_extend me on m.id = me.material_id and ifnull(me.delete_Flag,'0') !='1' and me.default_flag=1 left join jsh_material_current_stock mcs on m.id = mcs.material_id and ifnull(mcs.delete_flag,'0') !='1'
