and ifnull(m.delete_flag,'0') !='1' group by m.id, m.name, m.brand, m.mfrs, m.position, me.img_url, m.unit, mc.name, coalesce(nullif(me.sku_code,''), nullif(m.bar_code,'')), ifnull(me.purchase_decimal,0), ifnull(mcs.current_unit_price,0)
having ifnull(sum(mcs.current_number),0)!=0
